using Crown.Core;
using System.Text.Json.Nodes;

internal static class StageTwentySevenSpecs
{
    private static void Assert(bool x,string message){if(!x)throw new Exception(message);}
    internal static GameState Fixture(int era)
    {
        var s=World.Create();Narrative.Resolve(s,0);s.PendingEvent=null;s.ContinueAfterVictory=true;s.Units.Clear();
        foreach(var t in s.Tiles){t.Terrain=Terrain.Grassland;t.Owner=-1;t.Improvement=Improvement.None;t.Resource=Resource.None;t.Road=false;t.RoadOwner=-1;t.River=false;}
        (int X,int Y)[] at=[(12,12),(20,12),(30,20),(6,5)];foreach(var c in s.Cities){c.Tile=at[c.Owner].Y*s.Width+at[c.Owner].X;c.ProductionPaused=true;c.Food=500;c.Buildings.Clear();c.Prosperity=80;}
        foreach(var f in s.Factions){f.Gold=1000000;f.Research="";}var player=s.Player;player.Technologies.UnionWith(EpochCatalog.All.Take(era+1).SelectMany(e=>e.Technologies));for(int i=0;i<=era;i++)player.EpochChoices[i]=0;player.Stability=80;player.Commons=player.Scholars=80;
        var city=s.Cities[0];var other=Engine.AddCity(s,0,12*s.Width+16,"Próba sieci");other.ProductionPaused=true;other.Food=500;
        for(int x=12;x<=16;x++){var t=s.Tiles[12*s.Width+x];t.Road=true;t.RoadOwner=t.Owner=0;}
        s.Tiles[12*s.Width+11].Terrain=Terrain.Forest;
        foreach(int x in new[]{12,13}){var t=s.Tiles[11*s.Width+x];t.Owner=0;t.Improvement=Improvement.Farm;}
        city.MarketStocks[TradeGood.Iron]=50;
        string[][] ids=[[],[],["scribal_school","bronze_foundry"],[],["civic_forum","classical_academy","market"],["watermill","guild_hall"],["printing_house","powder_arsenal"],["public_lyceum","medical_college"],["steel_mill","rail_terminal"],["electric_grid","modern_hospital"],["atomic_reactor","rocket_centre"],["data_centre","recycling_district"],["robot_factory","genomic_clinic"],["fusion_plant","climate_restoration"],["zero_g_lab"],["exofarm"],["biosphere_habitat","deep_space_array"],["civilization_archive"]];
        city.Buildings.UnionWith(ids[era]);if(era>=8)city.Buildings.Add("stellar_collector");
        foreach(var p in Epochs.Programs.Where(p=>p.Era<=era))player.SpaceMilestones.Add(p.Id);
        s.InvalidateLogistics();return s;
    }
    private static void Step(GameState s)
    {
        if(s.PendingEvent!=null){var e=ProvincialEvents.Current(s);int choice=Enumerable.Range(0,e.Choices.Length).First(i=>s.Player.Gold+e.Choices[i].Gold>=0);Assert(Narrative.Resolve(s,choice).Success,"Council resolution failed");}
        s.Ending=null;Assert(Engine.EndTurn(s).Success,"Turn failed");
    }
    private static void Valid(GameState s)=>SaveGame.Deserialize(SaveGame.Serialize(s));
    public static void Run(Action<string,Action> test)
    {
        foreach(int era in Enumerable.Range(0,18))
        {
            int e=era;test("Era endeavour completes paid real phases: "+EpochCatalog.All[e].Name,()=>{var s=Fixture(e);Assert(EraEndeavours.Requirements(s,0,e).All(r=>r.Met),"Prepared requirements missing");Assert(EraEndeavours.Start(s,e,1).Success,"Start failed");for(int phase=0;phase<3;phase++){Step(s);Assert(s.Player.EraLegacies.Contains(e)==(phase==2),"Premature or missing legacy");Valid(s);}Assert(s.Player.ActiveEndeavour==-1&&s.Player.EndeavourProgress==0,"Completion retained an active plan");});
        }
        test("Every era has a distinct task legacy and architectural purpose",()=>{Assert(EraEndeavours.All.Length==18&&EraEndeavours.All.Select(x=>x.Name).Distinct().Count()==18&&EraEndeavours.All.Select(x=>x.Task).Distinct().Count()==18&&EraEndeavours.All.Select(x=>x.Legacy).Distinct().Count()==18,"Repeated era content");});
        test("Commissioning spends only the explicit start cost and grants no instant legacy",()=>{var s=Fixture(0);double gold=s.Player.Gold;Assert(EraEndeavours.Start(s,0,1).Success&&s.Player.Gold==gold-EraEndeavours.StartCost(0)&&s.Player.EndeavourProgress==0&&s.Player.EraLegacies.Count==0,"Instant or free legacy");Valid(s);});
        test("Rejected future duplicate owner and pace choices are atomic",()=>{var s=Fixture(0);string json=SaveGame.Serialize(s);Assert(!EraEndeavours.Start(s,1,0).Success&&!EraEndeavours.Start(s,0,2).Success&&!EraEndeavours.Start(s,0,0,8).Success&&SaveGame.Serialize(s)==json,"Rejected plan mutated state");EraEndeavours.Start(s,0,0);json=SaveGame.Serialize(s);Assert(!EraEndeavours.Start(s,0,1).Success&&!EraEndeavours.Cancel(s).Success&&SaveGame.Serialize(s)==json,"Multiple plans or same-turn cancellation");});
        test("Advancing an era preserves an unfinished historical commission",()=>{var s=Fixture(0);EraEndeavours.Start(s,0,0);Step(s);s.Player.Technologies.UnionWith(EpochCatalog.All[1].Technologies);s.Player.EpochChoices[1]=0;for(int i=0;i<5;i++)Step(s);Assert(s.Player.Era>=1&&s.Player.EraLegacies.Contains(0),"Era advancement erased the old commission");Valid(s);});
        test("An established legacy cannot be replayed for repeated rewards",()=>{var s=Fixture(0);EraEndeavours.Start(s,0,1);for(int i=0;i<3;i++)Step(s);string json=SaveGame.Serialize(s);Assert(!EraEndeavours.Start(s,0,0).Success&&SaveGame.Serialize(s)==json,"Repeated legacy mutated the campaign");});
        test("Foreign institutions cannot satisfy a domestic endeavour",()=>{var s=Fixture(6);s.Cities[0].Buildings.Remove("printing_house");s.Cities.First(c=>c.Owner==1).Buildings.Add("printing_house");Assert(EraEndeavours.Requirements(s,0,6).Any(r=>!r.Met),"Foreign printer fulfilled a domestic institution");});
        test("Forecasting all requirements preserves the complete campaign and RNG",()=>{var s=Fixture(17);string json=SaveGame.Serialize(s);foreach(int e in Enumerable.Range(0,18))EraEndeavours.Requirements(s,0,e);Assert(SaveGame.Serialize(s)==json,"Requirement preview mutated state");});
        test("Each funded phase spends the exact fee beyond ordinary economy",()=>{var s=Fixture(0);EraEndeavours.Start(s,0,1);var control=SaveGame.Deserialize(SaveGame.Serialize(s));control.Player.ActiveEndeavour=-1;control.Player.EndeavourStartedTurn=0;double before=s.Player.Gold;Step(s);Step(control);Assert(Math.Abs(control.Player.Gold-s.Player.Gold-EraEndeavours.Fee(0,1))<.00001&&s.Player.EndeavourProgress==1,"Phase fee duplicated or skipped");});
        test("Missing conditions reset continuity while retaining already paid costs",()=>{var s=Fixture(2);EraEndeavours.Start(s,2,1);Step(s);Assert(s.Player.EndeavourProgress==1,"First phase missing");s.Cities[0].Buildings.Remove("scribal_school");Step(s);Assert(s.Player.EndeavourProgress==0&&s.Player.EndeavourReport.Contains("Przerwana"),"Missing institution did not reset continuity");s.Cities[0].Buildings.Add("scribal_school");Step(s);Assert(s.Player.EndeavourProgress==1&&!s.Player.EraLegacies.Contains(2),"Old phase survived interruption");});
        test("The gradual plan actually needs six consecutive phases",()=>{var s=Fixture(0);EraEndeavours.Start(s,0,0);for(int i=0;i<5;i++)Step(s);Assert(s.Player.EndeavourProgress==5&&!s.Player.EraLegacies.Contains(0),"Gradual plan completed early");Step(s);Assert(s.Player.EraLegacies.Contains(0),"Sixth phase failed");});
        test("A cash shortage resets the plan without creating debt",()=>{var s=Fixture(17);s.Player.SpaceMilestones.Remove("ark_launch");EraEndeavours.Start(s,17,1);s.Player.Gold=0;foreach(var c in s.Cities.Where(c=>c.Owner==0))c.Unrest=100;Step(s);Assert(s.Player.EndeavourProgress==0&&s.Player.Gold>=0&&s.Player.EndeavourReport.Contains("Brak środków"),"Plan created debt or unearned phase");});
        test("Cancellation has no refund and cannot be used to restart in the same turn",()=>{var s=Fixture(0);EraEndeavours.Start(s,0,1);Step(s);double gold=s.Player.Gold;Assert(EraEndeavours.Cancel(s).Success&&s.Player.Gold==gold&&!EraEndeavours.Start(s,0,0).Success,"Cancellation refunded or bypassed cooldown");Valid(s);});
        test("Unpowered and suspended infrastructure never satisfies a powered endeavour",()=>{var s=Fixture(11);s.Cities[0].Buildings.Remove("stellar_collector");s.Player.EpochChoices.Clear();Assert(EraEndeavours.Requirements(s,0,11).Any(r=>!r.Met),"Zero generation counted as power");s.Cities[0].Buildings.Add("stellar_collector");s.Cities[0].SuspendedBuildings.Add("data_centre");Assert(EraEndeavours.Requirements(s,0,11).Any(r=>!r.Met),"Suspended data centre counted");});
        test("A newly built service cannot claim a phase before it actually received energy",()=>{var s=Fixture(11);var c=s.Cities[0];c.Buildings.Remove("data_centre");c.ProductionPaused=false;c.Project="data_centre";c.Production=1199.9;EraEndeavours.Start(s,11,1);Step(s);Assert(c.Buildings.Contains("data_centre")&&s.Player.EndeavourProgress==0,"A service absent from the phase stole a powered reading");Step(s);Assert(s.Player.EndeavourProgress==1,"Next actual powered service phase missing");});
        test("Legacy production is earned and follows the actual operating building",()=>{var s=Fixture(8);var c=s.Cities[0];Assert(EraEndeavours.Bonus(s,c).Production==0,"Unearned bonus");EraEndeavours.Start(s,8,1);for(int i=0;i<3;i++)Step(s);Assert(EraEndeavours.Bonus(s,c).Production==10,"Earned legacy absent");c.SuspendedBuildings.Add("steel_mill");Assert(EraEndeavours.Bonus(s,c).Production==0,"Suspended legacy bonus");});
        test("Transport housing and climate legacies change their actual systems",()=>{var s=Fixture(17);var c=s.Cities[0];c.Buildings.Add("medical_college");int supply=Epochs.Supply(s,0),housing=Epochs.Housing(s,c);double emissions=Epochs.Emissions(s,0);s.Player.EraLegacies.UnionWith([3,7,13]);Assert(Epochs.Supply(s,0)==supply+1&&Epochs.Housing(s,c)==housing+3&&Epochs.Emissions(s,0)==emissions-2*s.Cities.Count(c=>c.Owner==0),"Legacy did not affect real supply housing or emissions");});
        test("AI funds a legal available endeavour without steering the player",()=>{var s=Fixture(0);var f=s.Factions[1];var c=s.Cities.Single(c=>c.Owner==1);s.Tiles[World.Neighbors(s,c.Tile).First().Id].Terrain=Terrain.Forest;c.Food=500;Step(s);Assert(f.ActiveEndeavour==0&&f.EndeavourProgress==0&&s.Player.ActiveEndeavour==-1,"AI plan missing or player altered");Step(s);Assert(f.EndeavourProgress==1,"AI phase did not use ordinary rules");Valid(s);});
        test("A current save resumes the exact paid endeavour and future world",()=>{var s=Fixture(2);EraEndeavours.Start(s,2,0);Step(s);var copy=SaveGame.Deserialize(SaveGame.Serialize(s));for(int i=0;i<3;i++){Step(s);Step(copy);Assert(SaveGame.Serialize(s)==SaveGame.Serialize(copy),"Legacy continuation diverged");}});
        test("Actual v24 shape migrates without invented legacies and keeps an exact backup",()=>{var s=Fixture(4);s.ContinueAfterVictory=false;s.Cities[0].Buildings.Add(Manufacturing.Toolmakers);s.Cities[0].IndustryShare=25;s.Cities[0].MarketStocks[TradeGood.Tools]=12;var node=JsonNode.Parse(SaveGame.Serialize(s))!;node["Version"]=24;foreach(var f in node["Factions"]!.AsArray())foreach(string key in f!.AsObject().Select(p=>p.Key).Where(k=>k.Contains("Endeavour")||k=="EraLegacies").ToArray())f.AsObject().Remove(key);string old=node.ToJsonString();var loaded=SaveGame.Deserialize(old);Assert(loaded.Version==SaveGame.CurrentVersion&&loaded.Factions.All(f=>f.EraLegacies.Count==0&&f.ActiveEndeavour==-1)&&loaded.Cities[0].IndustryShare==25&&loaded.Cities[0].MarketStocks[TradeGood.Tools]==12,"Migration invented legacy or lost v24 industry");string dir=Path.Combine(Path.GetTempPath(),"crown-era-"+Guid.NewGuid());Directory.CreateDirectory(dir);string path=Path.Combine(dir,"old.crown");try{File.WriteAllText(path,old);SaveGame.Write(loaded,path);Assert(File.ReadAllText(path+".v24.bak")==old,"Exact v24 backup missing");}finally{foreach(string file in new[]{path,path+".tmp",path+".v24.bak"})File.Delete(file);Directory.Delete(dir);}});
        test("Validation rejects forged completed plans progress dates and legacy formats",()=>{for(int mode=0;mode<9;mode++){var s=Fixture(2);EraEndeavours.Start(s,2,1);switch(mode){case 0:s.Player.EraLegacies.Add(17);break;case 1:s.Player.EndeavourProgress=3;break;case 2:s.Player.LastEndeavourPhase=s.Turn;break;case 3:s.Player.EndeavourPace=8;break;case 4:s.Player.EraLegacies.Add(2);break;case 5:s.Player.EndeavourStartedTurn=0;break;case 6:s.Version=24;break;case 7:s.EpochCampaign=false;break;case 8:s.Player.ActiveEndeavour=-1;break;}bool rejected=false;try{Valid(s);}catch(InvalidDataException){rejected=true;}Assert(rejected,"Forged endeavour accepted");}});
    }
}
